def counting_sections_for_numbers(n, sections, count_of_numbers):
	count_section_for_numbers = [0] * count_of_numbers
	for section in sections:
		(l, r) = section
		count_section_for_numbers[l] += 1
		count_section_for_numbers[r] -= 1
	for i in range(count_of_numbers - 1):
		count_section_for_numbers[i + 1] += count_section_for_numbers[i]
	return count_section_for_numbers

def find_valid_sections(n, sections, count_sections_for_numbers, COUNT_OF_NUMBERS, count_numbers_in_two_sections, count_numbers_in_three_sections):
	valid_sections = []
	for i in range(n):
		(l, r) = sections[i]
		two_numbers_befor_section = count_numbers_in_two_sections[l] - count_numbers_in_two_sections[0]
		three_numbers_in_section = count_numbers_in_three_sections[l] - count_numbers_in_three_sections[r]
		two_numbers_after_section = count_numbers_in_two_sections[COUNT_OF_NUMBERS - 1] - count_numbers_in_two_sections[r]
		if two_numbers_after_section == 0 and two_numbers_befor_section == 0 and (three_numbers_in_section == 0):
			valid_sections.append(i + 1)
	return valid_sections

def counting_numbers_in_two_sections(count_sections_for_numbers):
	count_numbers_in_two_sections = [0]
	for i in range(1, len(count_sections_for_numbers)):
		current_number = count_numbers_in_two_sections[i - 1]
		if count_sections_for_numbers[i - 1] == 2:
			current_number += 1
		count_numbers_in_two_sections.append(current_number)
	return count_numbers_in_two_sections

def counting_numbers_in_three_sections(count_sections_for_numbers):
	count_numbers_in_three_sections = [0]
	for i in range(1, len(count_sections_for_numbers)):
		current_number = count_numbers_in_three_sections[i - 1]
		if count_sections_for_numbers[i - 1] >= 3:
			current_number += 1
		count_numbers_in_three_sections.append(current_number)
	return count_numbers_in_three_sections

def solve():
	(n, sections) = get_input()
	count_of_numbers = 1000000 + 1
	count_sections_for_numbers = counting_sections_for_numbers(n, sections, count_of_numbers)
	count_numbers_in_two_sections = counting_numbers_in_two_sections(count_sections_for_numbers)
	count_numbers_in_three_sections = counting_numbers_in_three_sections(count_sections_for_numbers)
	valid_sections = find_valid_sections(n, sections, count_sections_for_numbers, count_of_numbers, count_numbers_in_two_sections, count_numbers_in_three_sections)
	print(len(valid_sections))
	for section in valid_sections:
