def prefix_sum(ls):
	l1 = sorted(ls)
	(normal, inc) = ([ls[0]], [l1[0]])
	for i in range(1, len(ls)):
		normal.append(normal[i - 1] + ls[i])
		inc.append(inc[i - 1] + l1[i])
	return [normal, inc]

