from collections import defaultdict

class CumulativeSum:

	def __init__(self, l):
		self.dp = [0] * (len(l) + 1)
		for (i, v) in enumerate(l):
			self.dp[i + 1] = v + self.dp[i]

	def total(self, left, right):
		assert 0 <= left <= right < len(self.dp)
		return self.dp[right + 1] - self.dp[left]

def main():
