def solve():
	global N, T, fountain
	for x in range(T):
		fountain[0][0] += 1
		all_full = True
		for i in range(N - 1):
			for j in range(0, i + 1):
				glass = fountain[i][j]
				this_full = glass >= 0.9999
				all_full &= this_full
				if this_full:
					delta = (glass - 1) / 2
					fountain[i][j] = 1
					fountain[i + 1][j] += delta
					fountain[i + 1][j + 1] += delta
		for j in range(N):
			all_full &= fountain[N - 1][j] >= 0.9999
		if all_full:
			break
	cnt = 0
	for i in range(100):
		for j in range(0, i + 1):
			cnt = cnt + 1 if fountain[i][j] >= 0.9999 else cnt
	print(cnt)

