import sys
from time import time

def prime_gen(n):
	sieve = [1] * n
	for p in range(2, n):
		if sieve[p]:
			yield p
			for i in range(p + p, n, p):
				sieve[i] = 0

def pf_gen(n, pp):
	for p in pp:
		if p > n:
			break
		cnt = 0
		while n % p == 0:
			cnt += 1
			n //= p
		if cnt:
			yield (p, cnt)
	if n > 1:
		r = int(pow(n, 0.5))
		if r * r == n:
			yield (r, 2)
		else:
			yield (n, 1)

def get_sigmas(n, pp):
	(s0, s1) = (0, 1)
	for (p, c) in pf_gen(n, pp):
		s0 += 1
		s1 *= (pow(p, c + 1) - 1) // (p - 1)
	return (s0, s1)

def solve(aa):
	mx = max(aa)
	n = int(pow(mx, 1 / 3))
	tm = time()
	pp = list(prime_gen(n + 2500000))
	print('\tprimes generated: n=%d total=%d time elapsed=%s' % (n, len(pp), time() - tm), file=sys.stderr)
	cache = [0] * 4
	for a in aa:
		(s0, s1) = get_sigmas(a, pp)
		(p0, p1) = (s0 % 2, s1 % 2)
		cache[p0 + 2 * p1] += 1
	return max((cache[0] + cache[1], cache[0] + cache[2], cache[1] + cache[3], cache[2] + cache[3]))

