def GetRidOf2(n):
	while n % 2 == 0:
		n //= 2
	return n

def IsComposite(n, a, s, d):
	if pow(a, d, n) == 1:
		return False
	for r in range(s):
		if pow(a, (1 << r) * d, n) == n - 1:
			return False
	return True

def IsPrime(n):
	s = 0
	d = n - 1
	while d % 2 == 0:
		d >>= 1
		s += 1
	for a in witnesses:
