def get_power(a, b):
	if a == b:
		return 0
	return 1

def sum_power(x, N, K):
	sum = 0
	end = math.ceil(N / 2)
	max_prod = K if K <= end else N - K + 1
	for i in range(1, end + 1):
		temp = i
		if i > max_prod:
			temp = max_prod
		sum += temp * x[i - 1] + temp * x[N - i]
	if N % 2 == 1:
		sum -= temp * x[i - 1]
	return sum

