	first = prevplaced = intervals[1][0] - dist
	if not (first >= intervals[0][0] and first <= intervals[0][1]):
		if first > intervals[0][1]:
			first = prevplaced = intervals[0][1]
		else:
			first = prevplaced = intervals[0][0]
	for i in range(1, len(intervals)):
