class BinarySearchTree:

	def __init__(self):
		self.lcs = {}
		self.rcs = {}
		self.root = None

	def insert(self, key):
		if self.root is None:
			self.root = key
			self.lcs[key] = None
			self.rcs[key] = None
			return
		parent = self.root
		while True:
			if key < parent:
				if self.lcs[parent] is None:
					self.lcs[parent] = key
					self.lcs[key] = None
					self.rcs[key] = None
					break
				else:
					parent = self.lcs[parent]
			elif self.rcs[parent] is None:
				self.rcs[parent] = key
				self.lcs[key] = None
				self.rcs[key] = None
				break
			else:
				parent = self.rcs[parent]

	def _print(self, cur):
		self.preorder.append(cur)
		if self.lcs[cur]:
			self._print(self.lcs[cur])
		self.inorder.append(cur)
		if self.rcs[cur]:
			self._print(self.rcs[cur])

	def print(self):
		self.preorder = []
		self.inorder = []
		self._print(self.root)
		print(' ' + ' '.join(map(str, self.inorder)))
		print(' ' + ' '.join(map(str, self.preorder)))
