			a.append(self.value)
		if self.left:
			self.left.walk(a, walk_type)
		if walk_type == 1:
			a.append(self.value)
		if self.right:
			self.right.walk(a, walk_type)
		if walk_type == 2:
			a.append(self.value)
		return a

