		if self.root is None:
			self.root = Node(x)
			return
		(parent, current) = (None, self.root)
		while current:
			parent = current
			if x < current.value:
				current = current.left
			else:
				current = current.right
		if x < parent.value:
			parent.left = Node(x, parent)
		else:
			parent.right = Node(x, parent)

