	_lcm = lcm(a, b)
	prev = 0
	visits_a = visits_b = 0
	anext = a
	bnext = b
	while anext <= _lcm or bnext <= _lcm:
		if anext < bnext or (anext == bnext and a > b):
			d = anext - prev
			visits_a += d
			prev += d
			anext += a if anext + a <= _lcm else float('infinity')
		elif anext > bnext or (anext == bnext and a < b):
			d = bnext - prev
			visits_b += d
			prev += d
			bnext += b if bnext + b <= _lcm else float('infinity')
	if visits_a > visits_b:
		print('Dasha')
	elif visits_a < visits_b:
		print('Masha')
	else:
		print('Equal')
