import sys

class Main:

	def __init__(self):
		self.buff = None
		self.index = 0

	def next(self):
		if self.buff is None or self.index == len(self.buff):
			self.buff = sys.stdin.readline().split()
			self.index = 0
		val = self.buff[self.index]
		self.index += 1
		return val

	def next_int(self):
		return int(self.next())

	def solve(self):
		ss = self.next()
		ca = ss.count('a')
		l2 = (len(ss) - ca) // 2
		l1 = len(ss) - l2
		if list(filter(lambda x: x != 'a', ss[:l1])) == list(filter(lambda x: True, ss[l1:])):
			print(ss[:l1])
		else:
			print(':(')
