def binary_search(arr, n, x):
	l = 0
	r = n - 1
	ans = -1
	while l <= r:
		mid = int((l + r) / 2)
		if arr[mid] == x:
			return mid
		elif arr[mid] < x:
			l = mid + 1
		else:
			ans = mid
			r = mid - 1
	return ans
