def range_intersection(a, b, c, d):
	if a >= c - 1 and a <= d or (b >= c - 1 and b <= d):
		return True
	if c >= a - 1 and c <= b or (d >= a - 1 and d <= b):
		return True
	return False

def merge_ranges(a, b, c, d):
	k = a if a < c else c
	tot_dist = b - a + (d - c) + 1
	return (k, k + tot_dist)

def find_index(list, len_list, start):
	l = 0
	r = len_list
	while l < r:
		mid = (l + r) // 2
		if list[mid][0] <= start:
			l = mid + 1
		else:
			r = mid
	return l

